func ListSysRoleIDScope(ctx context.Context, db DBTX, params ListSysRoleIDScopeParams, opts ...dynq.QueryOption) (dynq.Result[SysRoleIDScope], error) {
	cfg, err := dynq.NewQueryConfig(sys_role_id_scopeRegistry, opts...)
	if err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	if err := validateSysRoleIDScopeParams(params, cfg); err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	limit, err := dynq.CheckPagination(sys_role_id_scopeRegistry, params.Limit, params.Offset, params.After)
	if err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	// 解析有效排序:未指定排序时回落表级 @default_sort。
	seq, err := dynq.ResolveSort(sys_role_id_scopeRegistry, cfg, params.OrderBy)
	if err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	fp := dynq.CursorFingerprint(sys_role_id_scopeRegistry.Resource, seq)
	// 计算 SELECT 列:投影列并集排序列(排序所需列始终参与查询)。
	cols := dynq.SelectColumns(sys_role_id_scopeRegistry, params.SelectFields, seq)
	b := sq.Select(cols...).From("sys_role_id_scope").PlaceholderFormat(sq.Dollar).Where(sq.And(buildSysRoleIDScopeWhere(params))).
		OrderBy(dynq.OrderBySQL(seq)).Limit(uint64(limit) + 1)
	// After 非 nil 时为游标模式:解码并校验游标,从该位置继续读取。
	if params.After != nil {
		vals, err := dynq.DecodeCursor(*params.After, fp, seq)
		if err != nil {
			return dynq.Result[SysRoleIDScope]{}, err
		}
		seek, err := dynq.SeekPredicate(seq, vals)
		if err != nil {
			return dynq.Result[SysRoleIDScope]{}, err
		}
		b = b.Where(seek)
	}
	if params.Offset > 0 {
		b = b.Offset(uint64(params.Offset))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	items, err := pgx.CollectRows(rows, pgx.RowToStructByNameLax[SysRoleIDScope])
	if err != nil {
		return dynq.Result[SysRoleIDScope]{}, err
	}
	// 以 LIMIT n+1 探测是否还有下一页,并构造 nextCursor。
	hasMore := len(items) > int(limit)
	if hasMore {
		items = items[:limit]
	}
	var next string
	if hasMore {
		next, err = dynq.EncodeCursor(fp, seq, sys_role_id_scopeCursorValues(items[len(items)-1], seq))
		if err != nil {
			return dynq.Result[SysRoleIDScope]{}, err
		}
	}
	return dynq.Result[SysRoleIDScope]{Items: items, HasMore: hasMore, NextCursor: next}, nil
}

